/* ================= v23: Songsterr-style tab engraving ================= */
/* Bars are laid out in justified rows, with rhythm stems and beams under the staff, technique marks
   (hammer-on and pull-off arcs, slides, bend arrows, vibrato, palm-mute brackets), chord names and a moving cursor. */
let TABW=0;function tabProWidth(){const w=TABW||innerWidth-40;return Math.max(300,Math.min(1180,w-10))}
/* the smooth cursor: glides from the note being played towards the next one */
function tabCursor(host,i,secs){const el=host.querySelector(`.tabpro [data-c="${i}"]`);if(!el)return;const svg=el.closest('svg');const c=svg.querySelector('.tcursor');if(!c)return;
 host.querySelectorAll('.tabpro .tcursor.on').forEach(x=>{if(x!==c)x.classList.remove('on')});const x=+el.getAttribute('x')+(+el.getAttribute('width')||0)/2;
 const nx=svg.querySelector(`[data-c="${i+1}"]`);c.classList.add('on');c.style.transition='none';c.style.transform=`translateX(${x}px)`;
 if(nx&&secs>0){void c.getBoundingClientRect();const x2=+nx.getAttribute('x')+(+nx.getAttribute('width')||0)/2;c.style.transition=`transform ${secs}s linear`;c.style.transform=`translateX(${x2}px)`}}

function songNotation(ex,mode){if(ex.view==='grid'||ex.view==='drumtab')return drumChart(ex.items,ex.steps,ex.per,ex.beats);
 if(ex.view==='chips')return`<div class="chips">${ex.items.map((it,i)=>`<span data-c="${i}">${esc(it.chordName||it.name)}</span>`).join('')}</div>`;
 if(ex.view==='stick')return`<div class="stk">${ex.items.map((it,i)=>`<span data-c="${i}" class="${it.acc?'acc':''}">${it.stick}</span>`).join('')}</div>`;
 const chunks=[];if(ex.lines)ex.lines.forEach(idx=>chunks.push({off:idx[0],items:idx.map(i=>ex.items[i])}));else for(let i=0;i<ex.items.length;i+=8)chunks.push({off:i,items:ex.items.slice(i,i+8)});
 const bar=ex.beats*ex.per;const lab=ch=>`<span class="tbar">${Math.floor(ch.items[0].st/bar)+1}</span>`;
 if(ex.view==='drumtab'){const rows=ROWS.map(r=>r[0]).filter(k=>ex.items.some(it=>it.hits&&it.hits[k]!=null));return chunks.map(ch=>`<div class="tline">${lab(ch)}<div class="scroll">${drumTabSVG(rows,ch.items.map(it=>it.hits||{}),ch.off)}</div></div>`).join('')}
 if(ex.items.length&&(mode==='staff'||mode==='both'||ex.view==='staff')&&(ex.S&&ex.items.every(it=>it.col||it.pos)||ex.items.every(it=>it.m!=null||it.chord))){return engrave(ex,ex.view==='staff'&&!(ex.S&&ex.items.every(it=>it.col||it.pos))?'staff':mode==='both'?'both':'staff')}
 if(false){const shift=ex.inst==='piano'?0:12;return chunks.map(ch=>{const clef=ex.inst==='bass'?'bass':ex.inst==='piano'&&Math.min(...ch.items.map(x=>x.m))<57?'bass':'treble';const evs=staffEvents(ex,ch);return`<div class="tline">${lab(ch)}<div class="scroll">${staff({clef,notes:evs.map(e=>e.rest?{rest:true,q:e.q}:{name:e.name,oct:octOf(e.name,e.m+shift),q:e.q}),idx0:ch.off})}</div></div>`}).join('')}
 if(ex.view==='tab'&&ex.S&&ex.items.every(it=>it.col||it.pos))return engrave(ex,'tab');
 return chunks.map(ch=>`<div class="tline">${lab(ch)}<div class="scroll">${tabSVG(ex.S,ch.items.map(it=>it.col||it.pos),-1,ch.off,ch.items.map(it=>it.mk||''),true)}</div></div>`).join('')}

