/* ---------- v10: profile, onboarding, per-instrument filtering ---------- */
const PROFILE=()=>store.get('profile',null);
const MYINST=()=>{const p=PROFILE();return p&&p.insts&&p.insts.length?p.insts:[INST()]};
function topicPool(insts=MYINST()){return TOPICS.filter(t=>t.id==='rhythm'||(t.inst?t.inst.some(i=>insts.includes(i)):insts.some(i=>i!=='drums'))).map(t=>t.id)}
function dailyPool(){return topicPool()}
const GENRES=[['folk','Folk & trad'],['rock','Rock'],['blues','Blues'],['metal','Metal'],['funk','Funk & soul'],['jazz','Jazz'],['pop','Pop'],['indie','Indie'],['classical','Classical'],['reggae','Reggae'],['cafe','French & café jazz'],['country','Country & Americana'],['soul','Soul & R&B'],['punk','Punk & post-punk']];
const GENRE_MAP={folk:['Folk & traditional','Classical'],rock:['Rock','Pop & rock','Prog','Reggae-rock'],blues:['Blues','Blues & rock and roll'],metal:['Metal'],funk:['Funk','Motown'],jazz:['Jazz'],pop:['Pop & rock','Motown','Indie'],indie:['Indie'],classical:['Classical'],reggae:['Reggae','Reggae-rock'],cafe:['French & café jazz','Jazz'],country:['Country & Americana','Folk & traditional'],soul:['Soul & R&B','Motown','Funk'],punk:['Punk & post-punk','Indie']};
function genreLiked(g){const p=PROFILE();return!!(p&&p.genres||[]).find(u=>(GENRE_MAP[u]||[]).includes(g))}
function jamFor(){const g=(PROFILE()||{}).genres||[];const m={blues:'blues',funk:'funk',jazz:'bossa',cafe:'gypsy',country:'altcountry',soul:'soul',punk:'punk',metal:'minor',reggae:'reggae',pop:'ballad',classical:'ballad',indie:'indie',rock:'rock'};for(const x of g)if(m[x])return m[x];return'rock'}
function greet(){const h=new Date().getHours();const p=PROFILE();const w=h<12?'Good morning':h<18?'Good afternoon':'Good evening';return p&&p.name?`${w}, ${p.name}`:w}
function myLessons(){const inst=INST();return[...instLearn(),...(inst!=='drums'?[...LEARN_THEORY,['rhythm','Rhythm & time']]:[])].filter((x,i,a)=>a.findIndex(y=>y[0]===x[0])===i)}
function likedSongs(inst=INST()){const out=[];(PLAYDB[inst]||[]).slice().sort((a,b)=>genreLiked(b.genre)-genreLiked(a.genre)).forEach(L=>L.songs.forEach(sg=>out.push({L,sg,liked:genreLiked(L.genre)})));return out}
function forYouHTML(){const inst=INST();const items=[];
 try{const done=store.get('planDone',{});const nx=planSeq().find(s=>!done[s.id]);if(nx)items.push(`<a class="fy" href="${nx.href||'#learn-'+nx.learn}"><span class="eyebrow">Next in your plan</span><b>${esc(nx.t)}</b><span class="hint">${esc(nx.sub||nx.topics.map(t=>TL[t]).join(', '))}</span></a>`)}catch(e){}
 const ls=likedSongs(inst);const pool=ls.filter(x=>x.liked).length?ls.filter(x=>x.liked):ls;if(pool.length){const x=pool[hashStr(todayKey()+inst)%pool.length];items.push(`<a class="fy" href="#song-${slug(inst+'-'+x.sg[0])}"><span class="eyebrow">Song of the day</span><b>${esc(x.sg[0])}</b><span class="hint">${esc(x.L.name)} · ${esc(x.L.genre)}</span></a>`)}
 const due=srsDue().length;if(due)items.unshift(`<a class="fy" href="#review"><span class="eyebrow">Review</span><b>${due} to review</b><span class="hint">Quick plays to keep them fresh</span></a>`);const w=weakest(1)[0];items.push(w?`<a class="fy" href="#practice" data-weak="${w}"><span class="eyebrow">Needs work</span><b>${esc(TL[w])}</b><span class="hint">Practise your weakest topic</span></a>`:`<a class="fy" href="#tools-jam"><span class="eyebrow">Warm up</span><b>Jam along</b><span class="hint">Play over a backing band</span></a>`);
 return`<section class="panel"><h3>For you</h3><div class="fygrid">${items.join('')}</div></section>`}
