/* settings */
function openSettings(){const ov=document.getElementById('setpanel'),body=document.getElementById('setbody');document.getElementById('sett').textContent='Settings';document.getElementById('setclose').textContent='Done';ov.dataset.welcome='';
 const render=()=>{const inst=INST_RAW();const str=inst==='guitar'||inst==='bass';const p=PROFILE()||{name:'',insts:[inst],level:LEVEL(),genres:[]};const mine=p.insts&&p.insts.length?p.insts:[inst];
  body.innerHTML=`<label class="onbf" for="setname">Your name<input id="setname" autocomplete="given-name" maxlength="40"></label>
  <div class="pickrow"><span class="eyebrow">Your instruments</span><div class="pills" data-multi="insts">${['guitar','bass','piano','drums','voice','ableton','logic','midi'].map(i=>`<button class="pill" data-v="${i}" aria-pressed="${mine.includes(i)}">${INST_NAME[i]}</button>`).join('')}</div>${mine.length>1?`<span class="eyebrow" style="margin-top:6px">Practising now</span>${pillsHTML('inst',mine.map(i=>[i,INST_NAME[i]]),inst)}`:''}<p class="hint">${INST_NOTE[inst]}</p></div>
  <div class="pickrow"><span class="eyebrow">Level</span>${pillsHTML('level',[['0','Beginner'],['1','Intermediate'],['2','Advanced']],String(LEVEL()))}</div>
  <div class="pickrow"><span class="eyebrow">Music you love</span><div class="pills" data-multi="genres">${GENRES.map(([k,n])=>`<button class="pill" data-v="${k}" aria-pressed="${(p.genres||[]).includes(k)}">${n}</button>`).join('')}</div></div>
  ${str?`<div class="pickrow"><span class="eyebrow">Hand</span>${pillsHTML('lefty',[['0','Right-handed'],['1','Left-handed']],LEFTY()?'1':'0')}<p class="hint">Left-handed mirrors fretboards and chord diagrams.</p></div>
  <div class="pickrow"><span class="eyebrow">Tuning</span>${pillsHTML('tuning',Object.entries(TUNINGS).map(([k,v])=>[k,v.name]),store.get('tuning','standard'))}</div>`:''}
  ${inst==='guitar'?`<div class="pickrow"><span class="eyebrow">Capo</span>${pillsHTML('capo',[0,1,2,3,4,5,7].map(n=>[String(n),n?'Fret '+n:'None']),String(CAPO()))}</div>`:''}
  <div class="pickrow"><span class="eyebrow">Tour</span><button class="btn small" id="settour">Take the tour again</button></div>${backupHTML()}<div class="pickrow"><label class="eyebrow" for="vol">Volume</label><input type="range" id="vol" min="0" max="1" step="0.05" value="${VOL()}"></div>
  <div class="row"><button class="btn small" id="rerun">Run setup again</button></div><p class="hint" id="syncnote">${syncText()}</p>
  <div class="pickrow"><span class="eyebrow">Instrument sound</span>${pillsHTML('snd',[['samples','Recorded samples'],['synth','Synthesised']],SND)}<p class="hint">Recorded samples sound like the real instruments. Synthesised sounds load instantly and use less memory.</p></div>
  <div class="pickrow"><span class="eyebrow">Guitar sound</span>${pillsHTML('gtone',GTONES,store.get('gtone','acoustic'))}</div>
  <div class="pickrow"><span class="eyebrow">Drum kit</span>${pillsHTML('dkit',Object.entries(DKITS).map(([k,x])=>[k,x.name]),store.get('dkit','rock'))}<p class="hint">Used on the drum pages. Jam along picks a kit to suit each style unless you change it there.</p></div>
  <details class="credits"><summary>Sound credits</summary><p class="hint">Piano: Salamander Grand Piano V3 by Alexander Holm, licensed <a href="https://creativecommons.org/licenses/by/3.0/" target="_blank" rel="noopener">CC BY 3.0</a>. Electric guitar and bass: tonejs-instruments by Nicholas Brosowsky (recorded electric bass from Freesound), licensed <a href="https://creativecommons.org/licenses/by/3.0/" target="_blank" rel="noopener">CC BY 3.0</a>. Acoustic guitar: MusyngKite SoundFont (acoustic steel-string guitar), licensed <a href="https://creativecommons.org/licenses/by-sa/3.0/" target="_blank" rel="noopener">CC BY-SA 3.0</a>, via the MIDI.js Soundfonts project by Benjamin Gleitzman. Notes were trimmed and re-encoded for this app.<br>Song transcriber note model: Basic Pitch by Spotify, licensed <a href="https://www.apache.org/licenses/LICENSE-2.0" target="_blank" rel="noopener">Apache 2.0</a>; run with ONNX Runtime by Microsoft (MIT).<br>Drums: Versilian Community Sample Library (VCSL) by Versilian Studios, released under CC0.</p></details>
  <div class="pickrow delzone"><span class="eyebrow">Delete my data</span><p class="hint">Removes your progress, plan, practice log, settings, imported tabs and recordings from this browser${CLOUD.db&&CLOUD.uid?', plus your synced progress and leaderboard scores from your Claude account':''}. Back up first if you might want it back.</p><div class="row"><button class="btn small danger" id="delall">Delete my data…</button></div><div class="delconf" id="delconf" hidden><p><b>Delete everything?</b> This can’t be undone.</p><div class="row"><button class="btn small dangerfill" id="delyes">Delete everything</button><button class="btn small" id="delno">Cancel</button></div></div><p class="hint" id="delmsg" aria-live="polite"></p></div>`;
  const save=patch=>{const cur=PROFILE()||{name:'',insts:[INST()],level:LEVEL(),genres:[]};store.set('profile',{...cur,...patch})};
  const nm=body.querySelector('#setname');nm.value=p.name||'';nm.onchange=()=>{save({name:nm.value.trim()});route()};
  body.querySelectorAll('[data-multi] .pill').forEach(b=>b.onclick=()=>{const grp=b.parentElement.dataset.multi;const v=b.dataset.v;const cur=PROFILE()||{insts:[INST()],genres:[]};let list=(cur[grp]||[]).slice();list=list.includes(v)?list.filter(x=>x!==v):[...list,v];
   if(grp==='insts'){if(!list.length)return;save({insts:list});if(!list.includes(INST()))store.set('inst',list[0]);store.set('ptopics',topicPool(list))}else save({genres:list});store.set('sgenre',null);render();syncHeader();route()});
  bindPills(body,(g,v)=>{if(g==='inst')store.set('inst',v);else if(g==='level'){store.set('level',+v);save({level:+v})}else if(g==='lefty')store.set('lefty',v==='1');else if(g==='tuning')store.set('tuning',v);else if(g==='snd'){SND=v;store.set('snd',v);if(v==='samples'){loadSamples('drums');loadSamples(TIMBRE())}render();return}else if(g==='gtone'){store.set('gtone',v);try{gtonePreview()}catch(e){}render();return}else if(g==='dkit'){store.set('dkit',v);const c=audio();if(c)['kick','hat','snare','hat'].forEach((d,i)=>drum(d,c.currentTime+.05+i*.17,1,v));render();return}else store.set('capo',+v);render();syncHeader();route()});
  {const tb=body.querySelector('#settour');if(tb)tb.onclick=()=>{const c=document.getElementById('setclose');if(c)c.click();setTimeout(startTour,250)}}
  bindBackup(body);const vol=body.querySelector('#vol');if(vol)vol.oninput=()=>{store.set('vol',+vol.value);if(MUTED())store.set('muted',false);applyVol();syncMute()};
  body.querySelector('#rerun').onclick=()=>{closeSettings();openOnboarding()};
  const dz=body.querySelector('.delzone');dz.querySelector('#delall').onclick=()=>{dz.querySelector('#delconf').hidden=false;dz.querySelector('#delall').hidden=true;dz.querySelector('#delno').focus()};dz.querySelector('#delno').onclick=()=>{dz.querySelector('#delconf').hidden=true;dz.querySelector('#delall').hidden=false;dz.querySelector('#delall').focus()};
  dz.querySelector('#delyes').onclick=async()=>{const b=dz.querySelector('#delyes'),msg=dz.querySelector('#delmsg');b.disabled=true;msg.textContent='Deleting…';const ok=await deleteMyData();if(!ok){b.disabled=false;msg.textContent='Your data was removed from this browser, but your Claude account copy couldn’t be deleted. Try again in a moment.';return}closeSettings();openOnboarding()}};

 render();ov.hidden=false;document.getElementById('setclose').focus()}
async function deleteMyData(){stopSeq();stopLoop();try{inputStop()}catch(e){}clearTimeout(pushT);let cloudOk=true;
 if(CLOUD.db&&CLOUD.uid){try{await pushBusy;await boardBusy}catch(e){}const r=await Promise.allSettled([CLOUD.db.doc('data/users/'+CLOUD.uid+'/state').delete(),CLOUD.db.doc('board/'+CLOUD.uid).delete()]);cloudOk=r.every(x=>x.status==='fulfilled');if(CLOUD.board)delete CLOUD.board[CLOUD.uid]}
 try{const ks=[];for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k&&k.startsWith('tc:'))ks.push(k)}ks.forEach(k=>localStorage.removeItem(k))}catch(e){}
 try{indexedDB.deleteDatabase('theory-club')}catch(e){}INPUT.lat=0;applyVol();syncMute();syncHeader();QUIZ=null;if(location.hash&&location.hash!=='#home')location.hash='#home';else route();return cloudOk}
function closeSettings(){document.getElementById('setpanel').hidden=true;const b=document.getElementById('setbtn');if(b)b.focus()}
document.getElementById('setbtn').onclick=()=>openSettings();

/* ---------- soloing ---------- */
const LICKS=[
 {id:'blues1',name:'Bluesy descent',style:'Blues · A minor pentatonic',bpm:84,desc:'Walks down box 1 and lands on a bend, then the root.',tab:'2|5:8 2|5:5 2|4:8 2|4:5 4|3:7|b 4|3:5 16|2:7|~'},
 {id:'rock1',name:'Rock repeater',style:'Rock · A minor pentatonic',bpm:96,desc:'A fast pull-off figure played three times, then a big bend. Repetition sounds exciting.',tab:'1|5:8 1|5:5|p 1|4:8 1|4:5 1|5:8 1|5:5|p 1|4:8 1|4:5 1|5:8 1|5:5|p 1|4:8 1|4:5 4|3:7|b 4|r 12|3:7|~'},
 {id:'call',name:'Call and response',style:'Any style · A minor pentatonic',bpm:88,desc:'A short question, a gap, then an answer that ends on the root.',tab:'2|3:7 2|3:5 4|2:7 8|r 2|4:5 2|4:8 4|3:7|b 8|r'},
 {id:'country',name:'Major pentatonic run',style:'Country & pop · A major pentatonic',bpm:100,desc:'Happy, open sound. Ends on A, the root.',tab:'2|3:2 2|3:4 2|4:2 2|4:5 4|5:2 4|5:5 4|4:5 2|4:2 2|3:4 8|3:2'},
 {id:'dorian',name:'Dorian climb',style:'Funk & Latin rock · A Dorian',bpm:92,desc:'Uses the bright 6th (F♯) that makes Dorian sound cool rather than sad.',tab:'2|2:7 2|2:9 2|3:7 2|3:9 2|3:11 2|4:8 2|4:10 2|4:8 4|3:11 4|3:9 8|2:7'},
 {id:'slide',name:'Sliding up the neck',style:'Rock · A minor pentatonic',bpm:80,desc:'Slides join box 1 to box 2 so you are not stuck in one place.',tab:'2|3:5 2|3:7 4|3:9|/ 2|4:8 2|4:10 4|4:8 2|3:9 2|3:7 4|3:5 8|2:7|~'}];
const SOLO_SCALE={rock:'majpent',blues:'blues',minor:'minpent',funk:'dorian',ballad:'major',bossa:'major'};


/* ---------- reading drum charts ---------- */
PAGES.charts=el=>{let gid='rock';const render=()=>{const ex=paBuild({type:'groove',groove:gid,key:'C'});ex.bpm=Math.min(GROOVES.find(g=>g.id===gid).bpm,96);
  el.innerHTML=`<span class="eyebrow">Drums</span><h1>Reading drum charts</h1><p>Drum music uses the same five-line staff as other instruments, but each line or space stands for a piece of the kit instead of a pitch. Cymbals are written with an × instead of a round note.</p>
  <section class="panel"><h3>Where each drum goes</h3>${drumKeyChart()}</section>
  <div class="cols"><div class="mini"><h4>Hands up, feet down</h4><p class="o">Notes played with sticks have stems going up. The kick drum, played with your foot, has stems going down.</p></div>
  <div class="mini"><h4>Read one beat at a time</h4><p class="o">Notes joined by a beam share one beat. One beam means eighth notes (“1 &”), two beams mean sixteenths (“1 e & a”).</p></div>
  <div class="mini"><h4>Ghost notes and accents</h4><p class="o">A note in brackets is a ghost note: play it very quietly. A small circle above the hi-hat means open it.</p></div>
  <div class="mini"><h4>Triplets</h4><p class="o">A 3 over a group means three notes in the space of two. Swing and shuffle grooves are written this way.</p></div></div>
  <section class="panel"><h3>Read and play</h3><p class="hint">Count out loud as the arrow moves, then play along.</p><div class="pickrow"><span class="eyebrow">Groove</span>${pillsHTML('g',GROOVES.map(g=>[g.id,g.name]),gid)}</div><div id="cplay" class="stack"></div></section>`;
  bindPills(el,(g,v)=>{gid=v;render()});mountPlayer(el.querySelector('#cplay'),ex)};render()};
